import { ApiDataInterface } from "../../../core";

/**
 * A one-time Connect Discord intent. Its id is a UUID the browser generates.
 */
export interface DiscordConnectIntentInterface extends ApiDataInterface {
  get returnPath(): string;
  get authorizeUrl(): string | undefined;
}

export type DiscordConnectIntentInput = {
  /** A UUID generated by the browser (uuid `v4()`). */
  id: string;
  /** Where the user lands after Discord: `/`, `/settings` or `/settings?section=<id>`. */
  returnPath: string;
};
